 "content": "def transform(grid):
    """Color the gaps between diamond centers sharing a row or column."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    twos = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 0 and all((rr, cc) in twos for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))):
                centers.append((r, c))

    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i + 1:]:
            if r1 == r2 and c1 != c2:
                lo, hi = sorted((c1, c2))
                for c in range(lo + 2, hi - 1):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2 and r1 != r2:
                lo, hi = sorted((r1, r2))
                for r in range(lo + 2, hi - 1):
                    if out[r][c1] == 0:
                        out[r][c1] = 1
    return out
